package net.lanbridge.android;

import android.app.*;
import android.content.*;
import android.os.*;
import android.view.*;
import android.view.accessibility.AccessibilityNodeInfo;
import android.widget.*;
import org.json.*;
import java.util.*;
import java.io.*;

/** Synthetic Provider + HTTP acceptance and real settings UI, on the explicit debug emulator only. */
public final class ParcelProcessingInstrumentation extends Instrumentation {
    private Bundle args;private MainActivity activity;private Throwable failure;private int checks;
    @Override public void onCreate(Bundle b){super.onCreate(b);args=b;start();}
    private void check(boolean ok,String label){checks++;if(!ok)throw new AssertionError(label);}
    private void main(Runnable action){runOnMainSync(()->{try{action.run();}catch(Throwable e){failure=e;}});if(failure!=null)throw new AssertionError(failure);waitForIdleSync();}
    private View find(View root,String text){if(root==null)return null;if(text.contentEquals(root.getContentDescription()==null?"":root.getContentDescription())||root instanceof TextView&&text.contentEquals(((TextView)root).getText()))return root;if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++){View found=find(((ViewGroup)root).getChildAt(i),text);if(found!=null)return found;}return null;}
    private Spinner thinking(View root){if(root instanceof Spinner&&"思考强度".contentEquals(root.getContentDescription()==null?"":root.getContentDescription()))return (Spinner)root;if(root instanceof ViewGroup)for(int i=0;i<((ViewGroup)root).getChildCount();i++){Spinner found=thinking(((ViewGroup)root).getChildAt(i));if(found!=null)return found;}return null;}
    private View page(String id){return activity.getFragmentManager().findFragmentByTag(id).getView();}
    private void click(String label){for(int attempt=0;attempt<30;attempt++){AccessibilityNodeInfo root=getUiAutomation().getRootInActiveWindow();if(root!=null)for(AccessibilityNodeInfo node:root.findAccessibilityNodeInfosByText(label)){if(!label.contentEquals(node.getText()))continue;while(node!=null&&!node.isClickable())node=node.getParent();if(node!=null&&node.performAction(AccessibilityNodeInfo.ACTION_CLICK)){SystemClock.sleep(100);waitForIdleSync();return;}}SystemClock.sleep(100);}throw new AssertionError("Missing action "+label);}
    private void text(String label,String value){AccessibilityNodeInfo root=getUiAutomation().getRootInActiveWindow();ArrayDeque<AccessibilityNodeInfo> queue=new ArrayDeque<>();queue.add(root);while(!queue.isEmpty()){AccessibilityNodeInfo node=queue.remove();if("android.widget.EditText".contentEquals(node.getClassName())&&label.contentEquals(node.getContentDescription()==null?"":node.getContentDescription())){Bundle b=new Bundle();b.putCharSequence(AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,value);check(node.performAction(AccessibilityNodeInfo.ACTION_SET_TEXT,b),"Set field "+label);waitForIdleSync();return;}for(int i=0;i<node.getChildCount();i++){AccessibilityNodeInfo child=node.getChild(i);if(child!=null)queue.add(child);}}throw new AssertionError("Missing field "+label);}
    private void keywords(){main(()->{activity.show("parcel");find(page("parcel"),"取件设置").performClick();});click("短信快速过滤");}
    private void capture(String name)throws Exception{SystemClock.sleep(150);android.graphics.Bitmap bitmap=getUiAutomation().takeScreenshot();try(FileOutputStream stream=new FileOutputStream(new File(getTargetContext().getExternalFilesDir(null),"parcel-processing-"+name+".png"))){bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG,100,stream);}bitmap.recycle();}
    private List<ParcelSms.Message> own(List<ParcelSms.Message> messages,String marker){List<ParcelSms.Message> result=new ArrayList<>();for(ParcelSms.Message message:messages)if(message.body.startsWith(marker))result.add(message);return result;}
    private void restore(SharedPreferences prefs,Map<String,?> values){SharedPreferences.Editor edit=prefs.edit().clear();for(Map.Entry<String,?> entry:values.entrySet()){Object value=entry.getValue();if(value instanceof Boolean)edit.putBoolean(entry.getKey(),(Boolean)value);else if(value instanceof String)edit.putString(entry.getKey(),(String)value);else if(value instanceof Integer)edit.putInt(entry.getKey(),(Integer)value);else if(value instanceof Long)edit.putLong(entry.getKey(),(Long)value);}edit.commit();}
    @Override public void onStart(){Context context=getTargetContext();Bundle result=new Bundle();JSONObject originalAi=null;SharedPreferences filter=context.getSharedPreferences("parcel-sms-filter",0),reasoning=context.getSharedPreferences("parcel-reasoning",0),automatic=ParcelAutoReader.prefs(context),local=context.getSharedPreferences("parcel-local",0);Map<String,?> oldFilter=filter.getAll(),oldReasoning=reasoning.getAll(),oldAuto=automatic.getAll(),oldLocal=local.getAll();String marker=args.getString("marker");boolean passed=false;
        try{
            check(context.getPackageName().endsWith(".debug"),"Debug emulator required");automatic.edit().putBoolean("enabled",false).commit();filter.edit().clear().commit();reasoning.edit().clear().commit();check(ParcelSmsFilter.load(context).enabled,"Filter not enabled by default");check(ParcelReasoning.load(context).equals("default"),"Thinking default changed");
            AiSettings settings=new AiSettings(context);originalAi=settings.exportSnapshot();String provider=settings.saveProvider("processing-fixture","Processing fixture","dashscope",args.getString("endpoint"),"fixture-key");settings.saveMultimodal(provider,"qwen3.8-flash");
            activity=(MainActivity)startActivitySync(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK).putExtra("page","parcel"));
            keywords();text("快递关键词（每行一个）","自定义站点");click("取消");check(ParcelSmsFilter.load(context).text.equals(ParcelSmsFilter.DEFAULT_KEYWORDS),"Canceled keywords saved");
            keywords();text("快递关键词（每行一个）","");click("保存");check(ParcelSmsFilter.load(context).text.equals(ParcelSmsFilter.DEFAULT_KEYWORDS),"Empty enabled filter accepted");text("快递关键词（每行一个）","自定义站点\n自定义站点");click("保存");check(ParcelSmsFilter.load(context).text.equals("自定义站点"),"Edited keyword not normalized/persisted");
            keywords();capture("custom-keywords");click("恢复默认");click("保存");check(ParcelSmsFilter.load(context).text.equals(ParcelSmsFilter.DEFAULT_KEYWORDS),"Restore default failed");
            keywords();capture("default-keywords");click("启用快递关键词过滤");click("保存");check(!ParcelSmsFilter.load(context).enabled,"Disable did not save");keywords();click("启用快递关键词过滤");click("保存");check(ParcelSmsFilter.load(context).enabled,"Enable did not save");
            main(()->activity.show("ai-settings"));main(()->{Spinner effort=thinking(page("ai-settings"));check(effort!=null&&effort.getSelectedItemPosition()==0,"Thinking selector missing/default wrong");effort.setSelection(3);});main(()->find(page("ai-settings"),"保存功能模型").performClick());check(ParcelReasoning.load(context).equals("medium"),"UI effort not saved");check(new AiSettings(context).parcelConfig(false).reasoning.equals("medium"),"Saved effort missing from runtime config");capture("thinking-medium");
            main(()->activity.show("parcel"));main(()->activity.show("ai-settings"));main(()->check((thinking(page("ai-settings"))).getSelectedItemPosition()==3,"Thinking setting not retained on return"));
            long now=System.currentTimeMillis();List<ParcelSms.Message> raw=own(ParcelSms.query(context,now-3600000,now+1000),marker);check(raw.size()==4,"Need four actual Provider fixtures");List<ParcelSms.Message> selected=own(ParcelSms.queryForImport(context,now-3600000,now+1000),marker);check(selected.size()==2,"Default filter did not keep only arrivals");
            int imported=ParcelAutoReader.importItems(context,selected,List.of(),new AiSettings(context).parcelConfig(false),false);check(imported==2,"Filtered manual import failed");try(ParcelStore store=new ParcelStore(context)){for(ParcelSms.Message source:raw)if(selected.stream().noneMatch(chosen->chosen.fingerprint.equals(source.fingerprint)))check(store.pendingSources(List.of(source)).size()==1,"Filtered out source marked processed");}
            ParcelSmsFilter.save(context,true,"自定义站点");List<ParcelSms.Message> custom=own(ParcelSms.queryForImport(context,now-3600000,now+1000),marker);check(custom.size()==1&&custom.get(0).body.contains("自定义站点"),"Custom keyword did not recover unprocessed SMS");ParcelAutoReader.configure(context,true,1);check(ParcelAutoReader.importItems(context,custom,List.of(),new AiSettings(context).parcelConfig(true),true)==1,"Filtered automatic import failed");ParcelAutoReader.configure(context,false,1);
            ParcelSmsFilter.save(context,false,"");check(own(ParcelSms.queryForImport(context,now-3600000,now+1000),marker).size()==4,"Filter disabled did not read all fixtures");
            try(ParcelStore store=new ParcelStore(context)){int parcels=0;for(ParcelStore.Parcel parcel:store.list(false,"address"))if(parcel.sources.stream().anyMatch(source->source.body.startsWith(marker))){parcels++;check(!parcel.code.isEmpty()&&parcel.sources.size()==1,"Imported parcel/source invalid");}check(parcels==3,"Expected three parcels, no verification-code parcel");}
            result.putString("stream","PASS: "+checks+" processing assertions: real Provider filtering, manual/automatic HTTP import, skipped-source recovery, keyword editing/defaults/cancel/disable and saved reasoning\n");passed=true;
        }catch(Throwable e){result.putString("stream",android.util.Log.getStackTraceString(e));}
        finally{try{automatic.edit().putBoolean("enabled",false).commit();if(marker!=null)try(ParcelStore store=new ParcelStore(context)){android.database.sqlite.SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{for(ParcelStore.Parcel parcel:store.list(false,"address"))if(parcel.sources.size()==1&&parcel.sources.get(0).body.startsWith(marker)){ParcelSms.Message source=parcel.sources.get(0);db.delete("parcels","id=?",new String[]{parcel.id});db.delete("sources","fingerprint=?",new String[]{source.fingerprint});db.delete("processed","fingerprint=?",new String[]{source.fingerprint});}db.setTransactionSuccessful();}finally{db.endTransaction();}}if(originalAi!=null)new AiSettings(context).importSnapshot(originalAi,new AiSettings(context).revision());restore(filter,oldFilter);restore(reasoning,oldReasoning);restore(automatic,oldAuto);restore(local,oldLocal);if(activity!=null){failure=null;main(()->activity.finish());}}catch(Exception e){android.util.Log.e("ParcelProcessingTest","Cleanup failed",e);passed=false;result.putString("stream","Cleanup failed: "+e.getClass().getSimpleName());}}
        finish(passed?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);
    }
}
